def divisors(n):
    d = []
    for j in range(2, int(n**0.5)+1):
        if n % j == 0:
            d += [j, n//j]
    return sorted(set(d))


cnt = 0
from itertools import permutations
for n in range(7_513_049, 10**10):
    d = [j for j in divisors(n) if len(divisors(j)) == 0 and str(j).count('1') > 0 and str(j).count('6') == 1]
    if len(d) > 0:
        for p in permutations(d, r=2):
            if p[0] * p[1] == n:
                print(n, max(p))
                cnt += 1
                break
        if cnt == 5:
            break
